package com.agrolink.controller;import com.agrolink.dto.review.*;import com.agrolink.service.ReviewService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/reviews") public class ReviewController{private final ReviewService s;public ReviewController(ReviewService s){this.s=s;}@PostMapping public ReviewResponse create(Authentication a,@Valid @RequestBody ReviewRequest r){return s.create(a.getName(),r);}@GetMapping("/product/{productId}") public List<ReviewResponse> product(@PathVariable Long productId){return s.productReviews(productId);}}
